create extension if not exists pgcrypto;
create table installations (id uuid primary key default gen_random_uuid(), name text not null, template_version text not null default '1.0.0', knowledge_version text not null default '0', created_at timestamptz not null default now());
create table knowledge_documents (id uuid primary key default gen_random_uuid(), installation_id uuid not null references installations(id) on delete cascade, document_id text not null, title text not null, category text not null, source_type text not null, version text not null, owner text not null, approval_status text not null check (approval_status in ('draft','approved','expired','withdrawn')), access_level text not null check (access_level in ('public','internal','restricted')), effective_date date, review_date date, expiry_date date, source_location text, content text not null, search_vector tsvector generated always as (to_tsvector('english', coalesce(title,'') || ' ' || coalesce(content,''))) stored, created_at timestamptz not null default now(), unique (installation_id, document_id, version));
create index knowledge_documents_search_idx on knowledge_documents using gin(search_vector);
create table enquiries (id uuid primary key default gen_random_uuid(), installation_id uuid not null references installations(id) on delete cascade, name text not null check (char_length(name) <= 160), email text not null check (char_length(email) <= 254), message text not null check (char_length(message) <= 2000), created_at timestamptz not null default now());
alter table installations enable row level security; alter table knowledge_documents enable row level security; alter table enquiries enable row level security;
create or replace function search_approved_knowledge(p_installation_id uuid, p_query text, p_limit int default 4) returns table(document_id text, title text, excerpt text, source_location text, rank real) language sql stable security invoker set search_path = public as $$ select kd.document_id, kd.title, ts_headline('english', kd.content, websearch_to_tsquery('english', p_query), 'MaxWords=55, MinWords=20'), kd.source_location, ts_rank(kd.search_vector, websearch_to_tsquery('english', p_query)) from knowledge_documents kd where kd.installation_id = p_installation_id and kd.approval_status = 'approved' and kd.access_level = 'public' and (kd.effective_date is null or kd.effective_date <= current_date) and (kd.expiry_date is null or kd.expiry_date > current_date) and kd.search_vector @@ websearch_to_tsquery('english', p_query) order by ts_rank(kd.search_vector, websearch_to_tsquery('english', p_query)) desc, kd.review_date desc nulls last limit greatest(1, least(p_limit, 10)); $$;
revoke all on installations, knowledge_documents, enquiries from anon, authenticated; revoke all on function search_approved_knowledge(uuid, text, int) from public;
